// Usage: npx tsx tru-run.mts <absolute path of page> [width=1280] [comma list of check names; default all]
// Runs the kit's page checks the way apps/studio/e2e/kit.e2e.ts does (each check sent into the page as text) and prints every finding that is not "holds", then the grade.
import { chromium } from './node_modules/playwright/index.mjs';
import { KIT_RULES, grade } from './packages/kit/src/index.ts';
import * as checks from './packages/kit/src/page-checks/index.ts';
const TOKENS = { '--ink': '#1a1a1a', '--paper': '#ffffff', '--accent': '#0b5fff', '--line': '#d0d5dd', '--radius': '8px', '--radius-in': '4px', '--font-body': 'Georgia, serif' };
const [file, width = '1280', only] = process.argv.slice(2);
const browser = await chromium.launch(process.env.PW_CHROMIUM ? { executablePath: process.env.PW_CHROMIUM } : {});
const context = await browser.newContext({ viewport: { width: Number(width), height: 800 }, deviceScaleFactor: 1 });
const page = await context.newPage();
await page.goto('file://' + file, { waitUntil: 'load' });
await page.waitForTimeout(400);
const findings: { ruleId: string; status: 'fails' | 'holds' | 'not-applicable' | 'could-not-measure' }[] = [];
// "var __name" only undoes a helper call that tsx adds to function text; vitest adds none.
for (const fn of only ? only.split(',') : Object.keys(checks)) findings.push(...await page.evaluate(`var __name = (f) => f; (${String((checks as Record<string, unknown>)[fn])})(document${fn === 'tokenFit' ? `, ${JSON.stringify(TOKENS)}` : ''})`) as typeof findings);
for (const f of findings) if (f.status !== 'holds' || only) console.log(JSON.stringify(f));
console.log(`holds ${findings.filter((f) => f.status === 'holds').length}, not-applicable ${findings.filter((f) => f.status === 'not-applicable').length}, fails ${findings.filter((f) => f.status === 'fails').length}`);
if (!only) console.log('grade with the window walk counted as held:', JSON.stringify(grade([...findings, { ruleId: 'behavior-dialog-keys', status: 'holds' }], KIT_RULES)));
await browser.close();
